const geminiResponse = $input.first().json;
const lessonData = $('Build Gemini QA Prompt').first().json;

// Extract the text from Gemini's response
let rawText = '';
try {
  rawText = geminiResponse.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Failed to extract Gemini response text: ' + e.message);
}

// Parse the JSON response
let qaResult;
try {
  // Remove any accidental markdown fences
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  qaResult = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse Gemini JSON response: ' + e.message + '\nRaw: ' + rawText.slice(0, 500));
}

const newScore = parseFloat(qaResult.qa_score) || 0;
const oldScore = parseFloat(lessonData.oldScore) || 0;
const scoreDelta = newScore - oldScore;

// Auto-downgrade status if score dropped significantly
let newPublicationStatus = null;
if (scoreDelta < -10) {
  newPublicationStatus = 'NEEDS_REVISION';
}

return [{
  json: {
    lessonID: lessonData.lessonID,
    oldScore,
    newScore,
    scoreDelta,
    oldVerdict: lessonData.oldVerdict,
    newVerdict: qaResult.qa_verdict,
    c1_ulc: qaResult.c1_ulc,
    c2_words: qaResult.c2_words,
    c3_brand: qaResult.c3_brand,
    c4_mission: qaResult.c4_mission,
    c5_content: qaResult.c5_content,
    c6_continuity: qaResult.c6_continuity,
    hardFailTriggered: qaResult.hard_fail_triggered,
    overrideReason: qaResult.override_reason,
    goldenExample: qaResult.golden_example,
    revisionPrompt: qaResult.revision_prompt,
    targetAgent: qaResult.target_agent,
    issues: qaResult.issues || [],
    newPublicationStatus
  }
}];

// Return a clean payload for Agent 16 to use in the Slack edit alert
const data = $('Parse Gemini Response').first().json;

return [{
  json: {
    lessonID: data.lessonID,
    old_score: data.oldScore,
    new_score: data.newScore,
    score_delta: data.scoreDelta,
    old_verdict: data.oldVerdict,
    new_verdict: data.newVerdict,
    golden_example: data.goldenExample,
    hard_fail_triggered: data.hardFailTriggered,
    issues_count: data.issues.length,
    status_changed_to: data.newPublicationStatus
  }
}];
